  "gl.thin.d": "Une capacité où vous êtes léger sur ce largage — toujours couverte par un coéquipier désigné. Consultez la matrice des capacités pour savoir qui.",
  "gl.reactive": "Gère l'appel des stratagèmes réactifs de l'escouade.",
  "tick.read.1": "Transmission de vos états de service au Haut Commandement de Super Terre…",
  "tick.read.2": "Recoupement de vos éliminations avec le ministère de la Vérité…",
  "tick.read.3": "Décompte de vos accidents. Avec indulgence.",
  "tick.read.4": "Lecture de chaque chiffre deux fois — la Liberté exige de la précision…",
  "tick.read.5": "Calibrage des indicateurs de liberté par minute…",
  "tick.read.6": "Vérification que vous n'êtes pas un Terminide en imperméable…",
