  "role.HARDPOINT.blurb": "Держит позицию. Строит зону поражения до контакта, чтобы освободить слоты отряда.",
  "role.HAMMER.blurb": "Противотанковый резерв отряда. Активирует цели, добивает то, что не добила зона поражения.",
