  "doctrine.commando.title": "코만도 교리",
  "doctrine.commando.1": "슈퍼 디스트로이어 창은 두 번, 각 60초 — 첫 창 전에 모든 호출을 계획하세요. 첫 번째 창: 임무 내내 들고 다닐 장비. 두 번째 창: 주 목표 또는 탈출.",
  "doctrine.commando.2": "지속 장비 먼저 (지원 무기, 백팩). 쓰러진 다이버는 장비를 떨어뜨립니다 — 회수하세요. 다음 창까지 재호출은 없습니다.",
  "doctrine.commando.3": "봇이 강하할 때마다 위협이 영구적으로 오릅니다. 조명탄과 호출병부터 처치하고, 순찰대는 우회하고, 샘플 때문에 싸우지 마세요.",
  "doctrine.commando.4": "증원은 4개의 포드(각 3목숨)에서 — 분대 전체 12회. 착지 시 표시하세요.",
  "d100.1": "D100 상시 명령: 주 목표를 완료할 때까지 보급 호출 금지.",
  "d100.2": "D100 상시 명령: 증원은 탈출 범위 안에서만 — 죽을 때마다 분대가 땅을 잃습니다.",
  "d100.3": "D100 상시 명령: S티어 목발 금지. 장비는 일부러 메타 밖입니다. 어떻게든 써먹으세요.",
  "note.plotting": "복잡한 스트라타젬 입력: 호출마다 2–4초 정지. 교전 중 호출은 즉응 다이버만, 나머지는 중계기 안에서 입력합니다.",
  "note.poor_intel": "정보 부족: Forward Eye가 한발 앞서 움직여, 넷이 다 같이 찾지 않아도 목표를 찾게 합니다.",
  "note.city": "도시 맵: 짧은 시야와 공중 위협. 거치 무기는 사계를 잃고, 대공과 진입 도구의 가치가 올라갑니다.",
  "note.mandated": "맵 필수: {list}.",
  "note.recovery": "복구: 교전 중에는 절대 증원하지 말 것. 마지막으로 완료한 단계부터 재개. 핵심 자산이 죽으면 돌아올 때까지 순서를 멈춤.",
