  "tick.read.1": "Ipinapadala ang career records mo sa Super Earth High Command…",
  "tick.read.2": "Kino-cross-check ang kill counts sa Ministry of Truth…",
  "tick.read.3": "Binibilang ang accidentals mo. Nang mapagbigay.",
  "tick.read.4": "Binabasa nang dalawang beses ang bawat numero — hinihingi ng Liberty ang accuracy…",
  "tick.read.5": "Kina-calibrate ang freedom-per-minute metrics…",
  "tick.read.6": "Kinukumpirmang hindi ka Terminid na naka-trench coat…",
  "tick.read.7": "Fini-file ang Form 27-B/Liberty nang triplicate…",
  "tick.read.8": "Humihingi ng orbital confirmation ng K/D mo…",
  "tick.read.9": "Nagtitimpla ng bagong tasa ng Liber-Tea…",
  "tick.read.10": "Kinukonsulta ang Democracy Officer para sa second opinion…",
  "tick.review.1": "Nagde-debrief kasama ang Ministry of Defense…",
  "tick.review.2": "Kinukumpara ang panunumpa mo sa official record…",
  "tick.review.3": "Nagpapakintab ng medalya… o naghahasa ng insulto…",
  "tick.review.4": "Binibilang ang mga bug, bot at pusit na na-liberate mo…",
  "tick.review.5": "Nirereview ang helmet-cam footage. Yung iba, dalawang beses.",
  "role.HARDPOINT.blurb": "Hawak ang posisyon. Binubuo ang killzone bago mag-contact para ma-free ang slots ng squad.",
  "role.HAMMER.blurb": "Ang anti-armor depth ng squad. Nag-a-arm ng objectives, pinapatay ang hindi kaya ng killzone.",
  "role.FORWARD_EYE.blurb": "Isang beat na nauuna. Sinosolusyunan ang poor intel; hindi kailanman nakikipaglaban sa laban ng squad.",
  "role.FIRES.blurb": "Isang mabigat na barrage sa minarkahang drop zone pagka-commit ng unang dropship.",
  "role.LONG_ARM.blurb": "Tuloy-tuloy na chaff clear at anti-air. Siya ang bahala sa volume para armor ang tutukan ng anchors.",
  "rat.read": "Ang read ay {driver}.",
  "rat.growth": "{item} ang growth pick — labas sa karaniwang abot ng {style}, inilagay kung saan nire-reward ng mission, hindi bilang handicap.",
  "rat.thin": "Manipis ang {axis} — malakas doon si {owner} at siya ang sasagot.",
  "rat.commando": "Commando op: walang statics — dalhin ang support weapon mo, magtabi ng isang strike para sa bawat Super Destroyer window.",
  "ps.siege_anchor.label": "Siege Anchor",
  "ps.siege_anchor.desc": "Humahawak at nagpapatibay ng posisyon — turrets, emplacements, nakahandang puwesto.",
  "ps.danger_close.label": "Danger Close",
  "ps.danger_close.desc": "Ordnance muna — Eagles at stratagems ang nangunguna sa bawat engagement.",
